// Draft generated by FreeLLMAPI (gpt-oss-20b via ovh); saved by Claude.

const { z } = require('zod');

const displayNameSchema = z
  .string()
  .trim()
  .min(1, { message: 'Display name must be at least 1 character' })
  .max(100, { message: 'Display name must be at most 100 characters' });

const bioSchema = z
  .string()
  .trim()
  .max(300, { message: 'Bio must be at most 300 characters' })
  .transform((v) => (v === '' ? null : v));

const avatarUrlSchema = z
  .string()
  .url({ message: 'Invalid URL' })
  .refine((url) => url.toLowerCase().startsWith('https://'), {
    message: 'URL must start with https://',
  })
  .max(500, { message: 'Avatar URL must be at most 500 characters' })
  .or(z.null())
  .transform((v) => (v === null ? null : v));

const updateProfile = z.object({
  displayName: displayNameSchema.optional(),
  bio: bioSchema.optional(),
  avatarUrl: avatarUrlSchema.optional(),
  isPrivate: z.boolean().optional(),
}).refine((data) => {
  return Object.keys(data).length > 0;
}, { message: 'At least one field must be provided' });

const usernameParams = z.object({
  username: z
    .string()
    .regex(/^[a-z0-9_.]{3,30}$/, {
      message: 'Username must be 3-30 characters, lowercase letters, numbers, _ or .',
    })
    .transform((s) => s.toLowerCase()),
});

const updateSettings = z.object({
  showOnlineStatus: z.boolean().optional(),
  likedPostsPrivate: z.boolean().optional(),
  allowMessagesFrom: z.enum(['everyone', 'followers', 'none']).optional(),
  language: z
    .string()
    .max(10, { message: 'Language must be at most 10 characters' })
    .or(z.null())
    .optional(),
});

const searchQuery = z.object({
  q: z.string().trim().min(1, { message: 'q must be at least 1 character' }).max(50, { message: 'q must be at most 50 characters' }),
  limit: z.coerce.number().int().min(1).max(20).default(10),
});

module.exports = {
  updateProfile,
  usernameParams,
  updateSettings,
  searchQuery,
};
